import { describe, it, expect, vi, beforeEach } from "vitest";
import { act, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { renderWithProviders } from "../tests/utils";
import { StandaloneHeader } from "./StandaloneHeader";
import { initInspectorStore, inspectorStore } from "../store";

describe("StandaloneHeader", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("renders Preview and Inspect options", () => {
    renderWithProviders(<StandaloneHeader />);
    expect(screen.getByText("Preview")).toBeInTheDocument();
    expect(screen.getByText("Inspect")).toBeInTheDocument();
  });

  it("renders the view control segment group", () => {
    renderWithProviders(<StandaloneHeader />);
    expect(screen.getByTestId("view-control")).toBeInTheDocument();
  });

  it("does not render agent name when assistantId is null", () => {
    renderWithProviders(<StandaloneHeader />, {
      initialStoreState: { assistantId: null },
    });
    expect(screen.queryByText("finance-bot")).not.toBeInTheDocument();
  });

  it("renders agent name when assistantId is set", () => {
    renderWithProviders(<StandaloneHeader />, {
      initialStoreState: { assistantId: "finance-bot" },
    });
    expect(screen.getByText("finance-bot")).toBeInTheDocument();
  });

  it("clicking Inspect sets inspectMode to true", async () => {
    const user = userEvent.setup();
    renderWithProviders(<StandaloneHeader />, {
      initialStoreState: { inspectMode: false },
    });

    await user.click(screen.getByText("Inspect"));
    expect(inspectorStore.state.inspectMode).toBe(true);
  });

  it("clicking Preview sets inspectMode to false", async () => {
    const user = userEvent.setup();
    renderWithProviders(<StandaloneHeader />, {
      initialStoreState: { inspectMode: true },
    });

    await user.click(screen.getByText("Preview"));
    expect(inspectorStore.state.inspectMode).toBe(false);
  });

  it("shows agent name set after initInspectorStore without remount (swi_1450)", () => {
    // Render StandaloneHeader — it subscribes to the current inspectorStore.
    renderWithProviders(<StandaloneHeader />);

    // Simulate InspectorContent calling initInspectorStore after siblings have
    // already rendered. Wrap in act() because setState notifies React subscribers.
    act(() => {
      initInspectorStore();
    });

    // useConversationData would then set assistantId on the store.
    act(() => {
      inspectorStore.setState((prev) => ({ ...prev, assistantId: "finance-bot" }));
    });

    // Agent name must be visible. Previously failed because initInspectorStore
    // replaced the store object, breaking the StandaloneHeader subscription.
    expect(screen.getByText("finance-bot")).toBeInTheDocument();
  });
});
